import re

def parse_duration(s: str) -> int:
    if not s:
        raise ValueError("Empty string")

    # Find all pairs of (digits, unit)
    matches = re.findall(r'(\d+)([hms])', s)

    # Reconstruct the string from matches to ensure the original string 
    # only contains valid components and no extra characters/spaces.
    if "".join(f"{val}{unit}" for val, unit in matches) != s:
        raise ValueError("Invalid duration format")

    unit_to_seconds = {'h': 3600, 'm': 60, 's': 1}
    return sum(int(val) * unit_to_seconds[unit] for val, unit in matches)
