import math

def compact(n: int) -> str:
    if n < 1000:
        return str(n)

    # Iterate through units from largest to smallest to ensure 
    # we pick the highest unit after rounding.
    for divisor, label in [(10**9, 'bi'), (10**6, 'mi'), (10**3, 'mil')]:
        val = n / divisor
        # Round half up to one decimal place
        rounded = math.floor(val * 10 + 0.5) / 10

        if rounded >= 1:
            # Format to one decimal place
            s = f"{rounded:.1f}"
            # Drop trailing '.0'
            if s.endswith(".0"):
                s = s[:-2]
            # Replace dot with comma as per Brazilian format
            return f"{s.replace('.', ',')} {label}"

    return str(n)
