import heapq

def build_order(deps: dict[str, list[str]]) -> list[str]:
    all_nodes = set(deps.keys())
    for d_list in deps.values():
        all_nodes.update(d_list)

    in_degree = {node: 0 for node in all_nodes}
    adj = {node: [] for node in all_nodes}

    for item, dependencies in deps.items():
        for dep in dependencies:
            adj[dep].append(item)
            in_degree[item] += 1

    # Kahn's algorithm using a min-heap for lexicographical order
    ready = [node for node in all_nodes if in_degree[node] == 0]
    heapq.heapify(ready)

    order = []
    while ready:
        u = heapq.heappop(ready)
        order.append(u)
        for v in adj[u]:
            in_degree[v] -= 1
            if in_degree[v] == 0:
                heapq.heappush(ready, v)

    if len(order) != len(all_nodes):
        raise ValueError("A cycle exists in the dependencies.")

    return order
