def wrap(text: str, width: int) -> list[str]:
    words = text.split()
    if not words:
        return []

    processed_words = []
    for w in words:
        if len(w) > width:
            for i in range(0, len(w), width):
                processed_words.append(w[i : i + width])
        else:
            processed_words.append(w)

    lines = []
    current_line = []
    current_length = 0

    for w in processed_words:
        if not current_line:
            current_line.append(w)
            current_length = len(w)
        else:
            if current_length + 1 + len(w) <= width:
                current_line.append(w)
                current_length += 1 + len(w)
            else:
                lines.append(" ".join(current_line))
                current_line = [w]
                current_length = len(w)

    if current_line:
        lines.append(" ".join(current_line))

    return lines
