def set_ini_value(text: str, section: str, key: str, value: str) -> str:
    lines = text.splitlines(keepends=True)
    new_lines = []
    section_found = False
    key_found = False
    current_section = None

    for line in lines:
        stripped = line.strip()

        # Check for section header: [section_name]
        if stripped.startswith('[') and ']' in stripped:
            start_idx = stripped.find('[') + 1
            end_idx = stripped.find(']')
            header_section = stripped[start_idx:end_idx]

            if header_section == section:
                section_found = True
            else:
                section_found = False

            current_section = header_section
            new_lines.append(line)
            continue

        # If we are inside the target section, look for the key
        if section_found and current_section == section:
            # A valid key-value line must contain '=' and not start with a comment char
            if '=' in stripped and not stripped.startswith((';', '#')):
                k_part, _ = stripped.split('=', 1)
                if k_part.strip() == key:
                    # Determine the original line ending to preserve it
                    if line.endswith('\r\n'):
                        ending = '\r\n'
                    elif line.endswith('\n'):
                        ending = '\n'
                    elif line.endswith('\r'):
                        ending = '\r'
                    else:
                        ending = ''

                    new_lines.append(f"{key} = {value}{ending}")
                    key_found = True
                    continue

        new_lines.append(line)

    if not section_found:
        raise KeyError(f"Section [{section}] not found")
    if not key_found:
        raise KeyError(f"Key '{key}' not found in section [{section}]")

    return "".join(new_lines)
