    # If core versions are equal, check pre-release existence
    # A release version has higher precedence than a pre-release version
    if v_a_pre is None and v_b_pre is not None:
        return 1
    if v_a_pre is not None and v_b_pre is None:
        return -1
    if v_a_pre is None and v_b_pre is None:
