import re

def parse_duration(s: str) -> int:
    if not s:
        raise ValueError("Invalid duration string")

    # Regex ensures components (h, m, s) appear in order and are optional
    # ^ and $ ensure the entire string is consumed to prevent invalid characters
    pattern = r'^(\d+h)?(\d+m)?(\d+s)?$'
    match = re.match(pattern, s)

    # If regex fails or if no units were found in a non-empty string
    if not match or not any(match.groups()):
        raise ValueError("Invalid duration string")

    total_seconds = 0
    for part in match.groups():
        if part:
            # Extract the numeric value and the unit character
            value = int(part[:-1])
            unit = part[-1]

            if unit == 'h':
                total_seconds += value * 3600
            elif unit == 'm':
                total_seconds += value * 60
            elif unit == 's':
                total_seconds += value

    return total_seconds
