import heapq

def build_order(deps: dict[str, list[str]]) -> list[str]:
    # Identify all unique nodes involved in the graph
    all_nodes = set(deps.keys())
    for dependencies in deps.values():
        for d in dependencies:
            all_nodes.add(d)

    # Initialize adjacency list and in-degree counts
    # adj[u] contains all nodes that depend on u
    adj = {node: [] for node in all_nodes}
    in_degree = {node: 0 for node in all_nodes}

    for item, dependencies in deps.items():
        for dep in dependencies:
            adj[dep].append(item)
            in_degree[item] += 1

    # Kahn's Algorithm: Initialize queue with nodes having 0 in-degree
    # We use a heap to ensure we always pick the alphabetically smallest node
    ready_queue = [node for node in all_nodes if in_degree[node] == 0]
    heapq.heapify(ready_queue)

    order = []
    while ready_queue:
        u = heapq.heappop(ready_queue)
        order.append(u)

        for v in adj[u]:
            in_degree[v] -= 1
            if in_degree[v] == 0:
                heapq.heappush(ready_queue, v)

    # If the order does not contain all nodes, there is a cycle
    if len(order) != len(all_nodes):
        raise ValueError("A cycle exists in the dependency graph.")

    return order
