def wrap(text: str, width: int) -> list[str]:
    words = text.split()
    if not words:
        return []

    processed_words = []
    for word in words:
        if len(word) <= width:
            processed_words.append(word)
        else:
            for i in range(0, len(word), width):
                processed_words.append(word[i:i + width])

    lines = []
    current_line = []
    current_length = 0

    for word in processed_words:
        word_len = len(word)
        if not current_line:
            current_line.append(word)
            current_length = word_len
        else:
            # Check if adding the word (plus a single space) exceeds width
            if current_length + 1 + word_len <= width:
                current_line.append(word)
                current_length += 1 + word_len
            else:
                lines.append(" ".join(current_line))
                current_line = [word]
                current_length = word_len

    if current_line:
        lines.append(" ".join(current_line))

    return lines
