def set_ini_value(text: str, section: str, key: str, value: str) -> str:
    lines = text.splitlines(keepends=True)
    new_lines = []
    in_target_section = False
    section_found = False
    key_updated = False

    for line in lines:
        stripped = line.strip()

        # Detect section header
        if stripped.startswith('[') and ']' in stripped:
            end_bracket = stripped.find(']')
            current_section = stripped[1:end_bracket]

            if current_section == section:
                if not section_found:
                    section_found = True
                # If we find the section again, we stay in the target section
                in_target_section = True
            else:
                # If we were in the target section and a new section starts, check if we found the key
                if in_target_section and not key_updated:
                    raise KeyError(f"Key '{key}' not found in section '{section}'")
                in_target_section = False

        # Check for the key within the target section
        if in_target_section and not key_updated:
            # Skip blank lines and comments
            if stripped and not (stripped.startswith(';') or stripped.startswith('#')):
                if '=' in line:
                    # Ensure it is not a section header by checking for '['
                    if not (stripped.startswith('[') and ']' in stripped):
                        parts = line.split('=', 1)
                        if parts[0].strip() == key:
                            # Prepare the new line with the required format
                            has_newline = line.endswith('\n') or line.endswith('\r')
                            new_line = f"{key} = {value}"
                            if has_newline:
                                if line.endswith('\r\n'):
                                    new_line += '\r\n'
                                else:
                                    new_line += '\n'

                            new_lines.append(new_line)
                            key_updated = True
                            continue

        new_lines.append(line)

    # Post-loop validation
    if not section_found:
        raise KeyError(f"Section '{section}' not found")
    if not key_updated:
        raise KeyError(f"Key '{key}' not found in section '{section}'")

    return "".join(new_lines)
