from datetime import datetime

def latest_by_key(records: list[dict], key: str) -> list[dict]:
    best_per_key = {}
    order = []

    for i, record in enumerate(records):
        val = record[key]
        # Parse ISO 8601 string. replace('Z', '+00:00') ensures compatibility with versions < 3.11.
        dt = datetime.fromisoformat(record['updated_at'].replace('Z', '+00:00'))

        if val not in best_per_key:
            order.append(val)
            best_per_key[val] = (dt, i, record)
        else:
            current_best_dt, current_best_idx, _ = best_per_key[val]
            # Update if the timestamp is later. 
            # If timestamps are equal, the record appearing later in the list (higher i) is kept.
            if dt > current_best_dt or (dt == current_best_dt and i > current_best_idx):
                best_per_key[val] = (dt, i, record)

    return [best_per_key[val][2] for val in order]
