import ipaddress

def ip_allowed(ip: str, networks: list[str]) -> bool:
    try:
        addr = ipaddress.ip_address(ip)
    except ValueError:
        return False

    # Create a list of IPs to check. 
    # If the IP is an IPv4-mapped IPv6 address, we include both the 
    # IPv6 address and its IPv4 equivalent to satisfy the requirement.
    ips_to_check = [addr]
    if addr.version == 6:
        mapped = addr.ipv4_mapped
        if mapped:
            ips_to_check.append(mapped)

    for net_str in networks:
        # strict=False allows networks with host bits set (e.g., '10.0.0.1/8')
        # If net_str is invalid, ip_network raises ValueError as required.
        net = ipaddress.ip_network(net_str, strict=False)
        if any(ip_obj in net for ip_obj in ips_to_check):
            return True

    return False
